fn zeros_like(a: &Vec<i32>) -> Vec<i32> {
    vec![0; a.len()]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty() {
        let a: Vec<i32> = Vec::new();
        let z = zeros_like(&a);
        assert_eq!(z.len(), 0);
        assert!(z.is_empty());
    }

    #[test]
    fn test_non_empty() {
        let a = vec![1, -2, 3, 42];
        let z = zeros_like(&a);
        assert_eq!(z.len(), a.len());
        assert!(z.iter().all(|&x| x == 0));

        // Check that adding z on either side leaves `a` unchanged
        let sum_left: Vec<i32> = z.iter().zip(a.iter()).map(|(&z, &x)| z + x).collect();
        let sum_right: Vec<i32> = a.iter().zip(z.iter()).map(|(&x, &z)| x + z).collect();
        assert_eq!(sum_left, a);
        assert_eq!(sum_right, a);
    }
}